import { Component } from "solid-js";

import { defineLegacyComponent } from "#core/ui-next/components/fxs-solid-component.js";
import { Icon } from "#core/ui-next/components/icon.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { Tooltip, TooltipHorizontalPosition, TooltipVerticalPosition } from "#core/ui-next/components/tooltip.jsx";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";

export declare interface ProductionChooserUniqueQuarterItemProps {
	name: string;
	description: string;
	currentCompleted: number;
	totalCompleted: number;
}

const ProductionChooserUniqueQuarterItemComponent: Component<ProductionChooserUniqueQuarterItemProps> = (props) => {
	return (
		<Tooltip.Text
			initialVPosition={TooltipVerticalPosition.CENTER}
			initialHPosition={TooltipHorizontalPosition.RIGHT}
			offset={30}
			text={props.description}
		>
			<div class="production-chooser-item flex items-stretch mb-2 ml-2 hover\\:text-accent-1 focus\\:text-accent-1">
				<Icon
					class="size-10 mr-2"
					name="CITY_UNIQUE_QUARTER"
				/>
				<div class="flex-auto flex flex-col">
					<div
						class="font-title text-base tracking-100 uppercase transition-color"
						data-l10n-id={props.name}
					/>
					<div
						class="font-body text-sm transition-color"
						data-l10n-id="LOC_UI_PRODUCTION_UNIQUE_QUARTER"
					/>
				</div>
				<div class="font-body text-sm self-end transition-color">
					<L10n.Compose
						text="LOC_UI_PRODUCTION_QUARTER_BUILDINGS_COMPLETED"
						args={[props.currentCompleted]}
					/>
				</div>
			</div>
		</Tooltip.Text>
	);
};

export const ProductionChooserUniqueQuarterItem = ComponentRegistry.register({
	name: "ProductionChooserUniqueQuarterItem",
	createInstance: ProductionChooserUniqueQuarterItemComponent,
});

defineLegacyComponent(
	"production-chooser-unique-quarter-item",
	{
		attrs: {
			"data-name": "",
			"data-description": "",
			"data-current-completed": "0",
			"data-total-completed": "2",
		},
	},
	(attrs) => {
		const name = attrs["data-name"] ?? "";
		const description = attrs["data-description"] ?? "";
		const currentCompleted = parseInt(attrs["data-current-completed"] ?? "0", 10);
		const totalCompleted = parseInt(attrs["data-total-completed"] ?? "2", 10);

		return (
			<ProductionChooserUniqueQuarterItem
				name={name}
				description={description}
				currentCompleted={currentCompleted}
				totalCompleted={totalCompleted}
			/>
		);
	},
);
